 internal static class FreeCanvasTests {
  static void Reject(Action action,Action<bool,string> check,string label){bool rejected=false;try{action();}catch{rejected=true;}check(rejected,label);}
  static void Wait(Func<bool> ready){DateTime end=DateTime.UtcNow.AddSeconds(30);while(!ready()&&DateTime.UtcNow<end){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);Thread.Sleep(1);}if(!ready())throw new Exception("Free canvas fixture timed out");}
  static void Await(Task task){Wait(()=>task.IsCompleted);task.GetAwaiter().GetResult();}
  static FreeCanvasItem Text(string value,double x,double y){return new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="text",Text=value,Color="auto",FontSize=22,X=x,Y=y,Width=280,Height=58};}
  static FreeCanvasItem Line(double x,double y,double endX,double endY){return new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="line",Color="auto",Stroke=3,X=x,Y=y,EndX=endX,EndY=endY};}
  internal static void Run(string root,Action<bool,string> check){
   Directory.CreateDirectory(root);string sources=Path.Combine(root,"sources");Directory.CreateDirectory(sources);string png=Path.Combine(sources,"参考 图片.png");using(var image=new Bitmap(600,400)){using(var g=System.Drawing.Graphics.FromImage(image)){g.Clear(System.Drawing.Color.FromArgb(45,100,145));g.FillRectangle(System.Drawing.Brushes.White,70,60,200,240);g.FillEllipse(System.Drawing.Brushes.Goldenrod,290,95,230,230);}image.Save(png,ImageFormat.Png);}byte[] sourceBytes=File.ReadAllBytes(png);DateTime sourceTime=File.GetLastWriteTimeUtc(png);
   Reject(()=>new FreeCanvasStore("relative"),check,"canvas data rejects relative destination");Reject(()=>new FreeCanvasStore("C:relative"),check,"canvas data rejects drive-relative destination");Reject(()=>new FreeCanvasStore(Path.GetPathRoot(root)),check,"canvas data rejects volume-root destination");Reject(()=>new FreeCanvasStore("\\\\server\\share\\canvas"),check,"canvas data remains in a local data folder");
   var store=new FreeCanvasStore(Path.Combine(root,"data"));check(store.List().Count==0,"canvas starts with no fabricated projects");var first=store.Create("机器人参考");check(first.Version==1&&store.List().Single().Name=="机器人参考","project creation writes a versioned named record");
   Reject(()=>store.Create(" "),check,"empty project name rejected");Reject(()=>store.Create(new string('x',121)),check,"overlong project names rejected");Reject(()=>store.Load("../outside"),check,"project path cannot escape data root");Reject(()=>store.ImagePath(first.Id,"../../outside.png"),check,"image path cannot escape project copies");Reject(()=>store.ImagePath(first.Id,new string('a',32)+".exe"),check,"image record cannot disguise executable content");
   var item=store.Import(first.Id,png,CancellationToken.None);first.Items.Add(item);first.Items.Add(Text("项目参考",22,20));first.Items.Add(Line(40,300,400,360));first.Pinned=true;first.Zoom=.7;first.PanX=-123;first.PanY=82;store.Save(first);string independent=store.ImagePath(first.Id,item.Image);
   check(File.Exists(independent)&&independent!=png&&File.ReadAllBytes(independent).SequenceEqual(sourceBytes),"canvas import commits an independent byte-identical copy using generated paths");check(File.ReadAllBytes(png).SequenceEqual(sourceBytes)&&File.GetLastWriteTimeUtc(png)==sourceTime,"canvas import does not edit original bytes or timestamp");check(item.Width==360&&item.Height==240,"first image is placed at useful reference size without altering copied resolution");using(var stream=new FileStream(png,FileMode.Open,FileAccess.ReadWrite,FileShare.None))check(stream.Length==sourceBytes.Length,"canvas import releases all original file handles");
   var loaded=store.Load(first.Id);check(loaded.Items.Count==3&&loaded.Items[1].Text=="项目参考"&&loaded.Pinned&&loaded.Zoom==.7&&loaded.PanX==-123&&loaded.PanY==82,"project reload retains image placement, text, line, pinning and viewport");check(File.Exists(Path.Combine(store.Root,first.Id,"project.json.bak")),"atomic save keeps the previous manifest backup");
   int copies=Directory.GetFiles(Path.GetDirectoryName(independent)).Length;Reject(()=>store.Import(first.Id,"https://example.com/picture.png",CancellationToken.None),check,"canvas does not fetch URL data or expose local network on drop");Reject(()=>store.Import(first.Id,sources,CancellationToken.None),check,"folder drops never expand all contained files");Reject(()=>store.Import(first.Id,"C:relative.png",CancellationToken.None),check,"image imports reject drive-relative path");Reject(()=>store.Import(first.Id,Path.Combine(sources,"missing.png"),CancellationToken.None),check,"missing image fails explicitly");string corrupt=Path.Combine(sources,"bad.png");File.WriteAllText(corrupt,"not a picture");Reject(()=>store.Import(first.Id,corrupt,CancellationToken.None),check,"invalid image is rejected rather than importing unusable record");var cancellation=new CancellationTokenSource();cancellation.Cancel();Reject(()=>store.Import(first.Id,png,cancellation.Token),check,"cancelled import cannot commit a partial managed image");check(Directory.GetFiles(Path.GetDirectoryName(independent)).Length==copies,"failed imports clean only their own temporary managed files");
   int width,height;var bounded=FreeCanvasStore.Decode(independent,independent,64,CancellationToken.None,out width,out height);check(width==600&&height==400&&bounded.IsFrozen&&bounded.PixelWidth<=64&&bounded.PixelHeight<=64,"preview decodes are frozen and bounded while retaining actual source dimensions");
   File.Move(png,png+".moved");try{check(store.Load(first.Id).Items.Count==3&&File.Exists(independent),"moving an original does not lose a saved canvas image");}finally{File.Move(png+".moved",png);}
   var stale=store.Load(first.Id);loaded.Name="已修改项目";store.Save(loaded);Reject(()=>store.Save(stale),check,"stale project instance cannot overwrite a newer record");check(store.Load(first.Id).Name=="已修改项目","failed stale save preserves actual newer project");
   var savedAs=store.SaveAs(loaded,"独立副本");check(savedAs.Id!=loaded.Id&&File.Exists(store.ImagePath(savedAs.Id,item.Image))&&store.Load(savedAs.Id).Items.Count==3,"save-as clones canvas and its own copies without linking mutable source project");var repeated=loaded.Items[0].Copy();repeated.Id=Guid.NewGuid().ToString("N");loaded.Items.Add(repeated);var sharedCopy=store.SaveAs(loaded,"重复引用");check(sharedCopy.Items.Count==4&&Directory.GetFiles(Path.GetDirectoryName(store.ImagePath(sharedCopy.Id,item.Image))).Length==1,"save-as handles separate items referencing the same image without copy collision");loaded.Items.Remove(repeated);string recycled=store.Trash(savedAs.Id);check(!store.List().Any(p=>p.Id==savedAs.Id)&&Directory.Exists(recycled)&&File.Exists(independent)&&File.ReadAllBytes(png).SequenceEqual(sourceBytes),"project deletion is recoverable and never deletes originals or another project's copies");check(store.RestoreLastDeleted()==savedAs.Id&&store.Load(savedAs.Id).Items.Count==3,"last deleted project can be restored with its images and annotations");
   string futureId=Guid.NewGuid().ToString("N"),futureFolder=Path.Combine(store.Root,futureId);Directory.CreateDirectory(futureFolder);string futureFile=Path.Combine(futureFolder,"project.json");string future="{\"Version\":99,\"Id\":\""+futureId+"\",\"Name\":\"newer\",\"Items\":[]}";File.WriteAllText(futureFile,future);Reject(()=>store.Load(futureId),check,"unknown future schema is rejected");check(store.List().Single(p=>p.Id==futureId).Error!=null&&File.ReadAllText(futureFile)==future,"future project remains listed as unreadable without silent replacement");
   string brokenId=Guid.NewGuid().ToString("N"),brokenFolder=Path.Combine(store.Root,brokenId);Directory.CreateDirectory(brokenFolder);string brokenFile=Path.Combine(brokenFolder,"project.json");File.WriteAllText(brokenFile,"{ incomplete");Reject(()=>store.Load(brokenId),check,"damaged JSON is rejected rather than turned into an empty canvas");check(File.ReadAllText(brokenFile)=="{ incomplete"&&store.List().Single(p=>p.Id==brokenId).Error!=null,"damaged original remains byte-for-byte intact and discoverable");
   var invalid=store.Load(first.Id);invalid.Items[0].Image="../../personal.png";Reject(()=>store.Save(invalid),check,"traversal record cannot be persisted");invalid=store.Load(first.Id);invalid.PanX=double.NaN;Reject(()=>store.Save(invalid),check,"non-finite canvas coordinates rejected");invalid=store.Load(first.Id);invalid.Items.Add(invalid.Items[0].Copy());Reject(()=>store.Save(invalid),check,"duplicate item IDs rejected to protect undo identity");
   var large=store.Create("没有固定图片数量上限");for(int i=0;i<2500;i++)large.Items.Add(new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="image",Image=item.Image,X=i*420.0,Y=-200000,Width=360,Height=240});store.Save(large);check(store.Load(large.Id).Items.Count==2500,"project has no small fixed image-count limit or bounded world canvas");
   var viewport=new FreeCanvasViewport{Zoom=.8,PanX=-340,PanY=220};var point=new System.Windows.Point(-15,31);var screen=viewport.Screen(point);check((viewport.World(screen)-point).Length<.00001,"canvas world/screen hit transforms are reversible with negative coordinates");var cursor=new System.Windows.Point(341,243);var anchor=viewport.World(cursor);viewport.ZoomAt(1.15,cursor);check((viewport.World(cursor)-anchor).Length<.00001,"wheel zoom preserves the world point below cursor");viewport.ZoomAt(10000,cursor);check(viewport.Zoom==16,"zoom upper bound protects viewport arithmetic without limiting item count");viewport.ZoomAt(.0000001,cursor);check(viewport.Zoom==.02,"zoom lower bound prevents division by zero");viewport.Fit(new[]{item},900,600);check(viewport.Screen(new System.Windows.Point(item.X,item.Y)).X>=40&&viewport.Zoom>0,"fit contains image within padded viewport");viewport.Fit(new FreeCanvasItem[0],900,600);check(viewport.Zoom==1&&viewport.PanX==0&&viewport.PanY==0,"empty fit returns a safe neutral viewport");
   var moving=Line(10,20,110,220);var initial=moving.Copy();FreeCanvasGeometry.Move(moving,initial,new System.Windows.Vector(-50,80));check(moving.X==-40&&moving.Y==100&&moving.EndX==60&&moving.EndY==300,"dragging a line translates both endpoints together");var resizing=item.Copy();var prior=resizing.Copy();FreeCanvasGeometry.Resize(resizing,prior,"nw",new System.Windows.Point(-120,-60),.7);check(Math.Abs(resizing.Width/resizing.Height-prior.Width/prior.Height)<.00001&&resizing.X+resizing.Width==prior.X+prior.Width&&resizing.Y+resizing.Height==prior.Y+prior.Height,"image corner resize retains original aspect ratio and the opposite fixed anchor");var text=Text("编辑",0,0);FreeCanvasGeometry.Resize(text,text.Copy(),"se",new System.Windows.Point(2000,1000),16);check(text.FontSize==22&&text.Width==2000,"text resize adjusts its writing box without exceeding allowed font size");check(FreeCanvasWindow.Editing(new TextBox())&&FreeCanvasWindow.Editing(new ComboBox()),"input controls are isolated from delete, undo and space-pan shortcuts");var child=new TextBlock();var comboItem=new ComboBoxItem{Content=child};check(FreeCanvasWindow.Editing(child),"nested selector content is isolated from canvas shortcuts too");
   Ui(root,png,sourceBytes,sourceTime,check);
   SelectionCanvasTests.Run(Path.Combine(root,"selection"),check);
   CanvasDrawingTests.Run(Path.Combine(root,"drawing"),check);
   FreeCanvasDesignFormatTests.Run(Path.Combine(root,"design-formats"),check);
  }
  static void Ui(string root,string source,byte[] bytes,DateTime modified,Action<bool,string> check){
   var app=Application.Current??new Application();string previous=Theme.Current;var context=SynchronizationContext.Current;SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(app.Dispatcher));FreeCanvasWindow window=null,undoWindow=null,preferencesWindow=null;
   try{Theme.Set("light");window=new FreeCanvasWindow(Path.Combine(root,"ui-data"),new Settings());check(!window.IsVisible&&window.Owner==null,"canvas is constructed without showing or being owned by a library window");check(window.PreviewBudgetForTests==FreeCanvasWindow.PreviewBudget&&window.SaveDelayForTests==1200&&!window.DocumentForTests.Pinned,"default canvas preferences keep 48 MB cache, 1.2 second autosave and no forced pinning");Await(window.ImportImagesAsync(new[]{source},new System.Windows.Point(80,100)));var image=window.DocumentForTests.Items.Single();string copy=new FreeCanvasStore(Path.Combine(root,"ui-data")).ImagePath(window.DocumentForTests.Id,image.Image);check(image.X==80&&image.Y==100&&File.ReadAllBytes(copy).SequenceEqual(bytes),"actual asynchronous add uses drop world coordinates and independent image copy");var annotation=Text("参考图 / 项目一",470,122);var line=Line(455,235,730,265);window.DrawItemForTests(annotation);window.DrawItemForTests(line);window.DeleteForTests(image.Id,annotation.Id);check(window.DocumentForTests.Items.Count==1&&window.DocumentForTests.Items[0].Kind=="line"&&File.Exists(copy)&&File.ReadAllBytes(source).SequenceEqual(bytes),"actual multi-delete only removes selected canvas records, never copied image bytes or source");window.UndoForTests();check(window.DocumentForTests.Items.Count==3&&window.DocumentForTests.Items[0].Id==image.Id&&window.DocumentForTests.Items[1].Id==annotation.Id,"Ctrl+Z deletion action restores item identity and original z-order");check(window.SaveForTests()&&!window.DirtyForTests,"manual save clears dirty state only after atomic commit");
    foreach(string theme in new[]{"light","dark"}){Theme.Set(theme);Render(window,root,theme,check);Wait(()=>window.PreviewBytesForTests>0);Render(window,root,theme,check);check(window.PreviewBytesForTests<=FreeCanvasWindow.PreviewBudget,"visible image preview cache stays below shared 48 MB budget in "+theme+" theme");}
    image.X=500000;window.DrawItemForTests(Text("远处",510000,500000));window.FitForTests();check(window.DirtyForTests,"fit and viewport changes participate in project persistence");window.SaveForTests();check(window.PrepareExit()&&File.ReadAllBytes(source).SequenceEqual(bytes)&&File.GetLastWriteTimeUtc(source)==modified,"exit preparation preserves original image and saves current project without closing it");check(!window.IsVisible,"canvas UI fixtures never display a test window");
    undoWindow=new FreeCanvasWindow(Path.Combine(root,"undo-ui-data"),new Settings());Await(undoWindow.ImportImagesAsync(new[]{source},new System.Windows.Point(10,20)));var inserted=undoWindow.DocumentForTests.Items[0];undoWindow.MoveForTests(inserted.Id,new System.Windows.Vector(100,-60));check(undoWindow.DocumentForTests.Items[0].X==110&&undoWindow.DocumentForTests.Items[0].Y==-40,"actual move command translates a selected image in world coordinates");undoWindow.UndoForTests();check(undoWindow.DocumentForTests.Items[0].X==10&&undoWindow.DocumentForTests.Items[0].Y==20,"actual move undo restores item coordinates");undoWindow.UndoForTests();check(undoWindow.DocumentForTests.Items.Count==0,"undoing import still removes the item after move undo replaced its object instance");undoWindow.DrawItemForTests(Text("未保存内容",10,10));undoWindow.SaveForTests();string manifest=Path.Combine(root,"undo-ui-data","free-canvas",undoWindow.DocumentForTests.Id,"project.json");byte[] intact=File.ReadAllBytes(manifest);File.WriteAllText(manifest,"externally damaged");undoWindow.DrawItemForTests(Text("需要保留",10,60));int notices=0;undoWindow.SaveFailureForTests=message=>notices++;check(!undoWindow.PrepareExit()&&undoWindow.DirtyForTests&&notices==1&&File.ReadAllText(manifest)=="externally damaged","failed exit save reports a warning, retains dirty work and refuses to overwrite damaged record");undoWindow.Close();check(!undoWindow.ClosedForTests&&notices==2,"actual window close is cancelled when unsaved project cannot be committed");File.WriteAllBytes(manifest,intact);check(undoWindow.SaveForTests()&&undoWindow.PrepareExit(),"restoring the intact manifest permits an explicit save and safe exit");
    var drop=new DataObject();drop.SetData("PNG",bytes);var payload=DesktopImageDrop.Capture(drop);drop.SetData("PNG",new byte[]{0});Await(undoWindow.ImportPayloadAsync(payload,new System.Windows.Point(70,90)));var received=undoWindow.DocumentForTests.Items.Last();string ownCopy=new FreeCanvasStore(Path.Combine(root,"undo-ui-data")).ImagePath(undoWindow.DocumentForTests.Id,received.Image);check(received.Kind=="image"&&received.X==70&&received.Y==90&&File.ReadAllBytes(ownCopy).SequenceEqual(bytes),"captured virtual desktop image survives source payload release and commits into the canvas");check(!File.Exists(received.Source),"temporary desktop-image stage is removed after independent canvas copy commits");
    preferencesWindow=new FreeCanvasWindow(Path.Combine(root,"preferences-data"),new Settings{CanvasDefaultTopmost=true,CanvasCacheMB=16,CanvasSaveDelay=9000});check(preferencesWindow.DocumentForTests.Pinned&&preferencesWindow.Topmost&&preferencesWindow.SaveDelayForTests==9000&&preferencesWindow.PreviewBudgetForTests==16L*1024*1024,"custom canvas preferences control new-project pinning, autosave delay and preview budget");preferencesWindow.Close();preferencesWindow=new FreeCanvasWindow(Path.Combine(root,"preferences-data"),new Settings{CanvasDefaultTopmost=false});check(preferencesWindow.DocumentForTests.Pinned&&preferencesWindow.Topmost,"changing default pin preference does not overwrite an existing project's saved pin state");
   }finally{if(window!=null)window.Close();if(undoWindow!=null)undoWindow.Close();if(preferencesWindow!=null)preferencesWindow.Close();Theme.Set(previous);SynchronizationContext.SetSynchronizationContext(context);}
   var store=new FreeCanvasStore(Path.Combine(root,"ui-data"));var current=store.Load(store.List().First(p=>p.Error==null).Id);check(current.Items.Count==4&&current.Items.Any(i=>i.Text=="远处"),"closed canvas reload retains committed images, annotations and viewport");
  }
  static void Render(FreeCanvasWindow window,string root,string theme,Action<bool,string> check){
   var content=(FrameworkElement)window.Content;content.Width=1120;content.Height=700;content.Measure(new System.Windows.Size(1120,700));content.Arrange(new Rect(0,0,1120,700));content.UpdateLayout();var bitmap=new RenderTargetBitmap(1120,700,96,96,PixelFormats.Pbgra32);bitmap.Render(content);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(Path.Combine(root,"free-canvas-"+theme+".png")))encoder.Save(output);byte[] pixel=new byte[4];bitmap.CopyPixels(new Int32Rect(1090,600,1,1),pixel,4,0);var expected=((SolidColorBrush)Theme.Brush("Canvas")).Color;check(!window.IsVisible&&pixel[0]==expected.B&&pixel[1]==expected.G&&pixel[2]==expected.R&&pixel[3]==255,theme+" actual canvas renders an opaque neutral background offscreen without touching desktop");
  }
 }
